import { Controller } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { DeviceManager } from '../services/deviceManager';

interface CameraFeedPayload {
  deviceSerial: string;
  householdUserId: string;
}

@Controller()
export class CameraEventController {
  constructor(private readonly deviceManager: DeviceManager) {}

  @MessagePattern('iot.security.feed')
  async getCameraFeed(@Payload() data: CameraFeedPayload) {
    if (!data.householdUserId) {
      return { error: 'Household user authorization missing', status: 401 };
    }

    const camera = await this.deviceManager.lookupCamera(data.deviceSerial);
    if (!camera) {
      return { error: 'Camera offline or not found', status: 404 };
    }

    // Verify user belongs to the household registered to the camera
    const isOwner = await this.deviceManager.verifyOwnership(camera.serial, data.householdUserId);
    if (!isOwner) {
      return { error: 'Forbidden: camera belongs to another household', status: 403 };
    }

    return {
      deviceSerial: camera.serial,
      liveRtspStreamUrl: camera.streamUri,
      latestMotionSnapshot: camera.lastSnapshotBase64
    };
  }
}
